<?php
require_once __DIR__.'/../includes/functions.php';require_login();require_once __DIR__.'/../config/database.php';$st=$pdo->prepare("SELECT a.assessment_id,a.readiness_score,a.completed_at,j.role_name FROM assessments a JOIN job_roles j ON j.job_role_id=a.job_role_id WHERE a.user_id=? AND a.status='completed' ORDER BY a.completed_at DESC");$st->execute([(int)current_user()['user_id']]);$rows=$st->fetchAll();$pageTitle='Assessment history';$active='dashboard';include __DIR__.'/../includes/header.php';?>
<main class="main"><div class="container section-sm"><div class="page-head"><div><span class="eyebrow">Your assessment journey</span><h1 class="h1">Assessment history</h1><p>Review previous skill coverage snapshots and revisit their reports.</p></div><a class="btn btn-primary" href="<?=h(url('careers/index.php'))?>">Start an assessment</a></div><section class="card card-pad"><div class="table-wrap"><table class="table"><thead><tr><th>Career role</th><th>Skill coverage</th><th>Completed</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=h($r['role_name'])?></strong></td><td><span class="pill pill-blue"><?=number_format((float)$r['readiness_score'],1)?>%</span></td><td><?=date('d M Y',strtotime($r['completed_at']))?></td><td><a class="link-arrow" href="<?=h(url('assessment/result.php?id='.(int)$r['assessment_id']))?>">View report →</a></td></tr><?php endforeach;?></tbody></table></div><?php if(!$rows):?><div class="empty-state"><div class="empty-icon">◎</div><h2>No assessments yet</h2><p>Select a career role to create your first skill assessment.</p><a class="btn btn-primary" href="<?=h(url('careers/index.php'))?>">Explore careers</a></div><?php endif;?></section></div></main><?php include __DIR__.'/../includes/footer.php';?>
